PROCESS = [
    ("A worked planning example", "For {setting}, start with one ordinary day rather than the most ambitious future arrangement. Write down the sequence of work and the point at which a decision is needed. For this article, the central concern is {focus} Keep that concern visible when reviewing options. A solution that improves an unrelated activity may be useful later, but it should not replace the question being investigated. Explain the expected benefit in language the person doing the work can challenge."),
    ("Compare two practical options", "Create a simple comparison between keeping the current arrangement and making the proposed change. Include time, space, training and maintenance, not only the initial purchase or setup. In {setting}, an apparently small adjustment can move work to another person. Ask that person to inspect the proposal before declaring it more efficient. Record unresolved questions and avoid giving invented numerical savings to a change that has not been measured."),
    ("Keep the trial reversible", "Use a temporary arrangement where practical and retain the information needed to restore the previous setup. Tell affected people when the trial starts and what should be observed. Do not treat participation as agreement that the idea is successful. Invite concrete examples of inconvenience as well as improvement. A reversible trial makes it easier to learn without committing resources to an arrangement whose advantages are still uncertain."),
    ("An example of misleading evidence", "Suppose a short trial seems easier on a quiet day. Before adopting the change, ask whether demand, staffing or the material being handled also changed. The comparison may still be useful, but those conditions belong in the conclusion. In {setting}, the same result may not carry over to a crowded session. Keep the original notes so the group can distinguish what was observed from the explanation first proposed for it."),
    ("Make the handover usable", "Leave a short note describing the agreed arrangement, who is responsible for maintaining it and what should trigger a review. Put the note where the next person will actually look. A procedure hidden in an old email is unlikely to guide daily work. Include the exception that caused the most discussion during the trial, because that is often the situation in which a new person needs the clearest instruction."),
    ("Questions before spending more", "Before expanding the change, ask whether the original problem remains, whether a simpler adjustment would address it and whether the necessary support is available. Separate an essential requirement from a preference. Where specialist advice or permission is needed, obtain it before acting. This fictional article illustrates a decision process; it does not establish a universal specification, a financial return or permission to disregard the instructions relevant to a real setting."),
    ("Review after the first week", "Return to the original concern and compare a few ordinary observations from before and after the trial. Look for repeated patterns rather than selecting the most flattering example. If the evidence is mixed, state which tasks improved and which remained difficult. Keep the change only when its trade-offs are understood. The record should help the next review begin from evidence rather than restarting the same discussion from memory."),
    ("Explain the remaining uncertainty", "A practical guide cannot anticipate every local condition. List the assumptions that matter most and explain what additional information would change the recommendation. In {setting}, the available space, experience and schedule may differ from this example. Readers should adapt the reasoning to their own circumstances rather than copy an isolated instruction. Where the consequences are significant, ask an appropriately qualified person to review the proposed action."),
]


def build():
    rows = []
    for topic, spec in TOPICS.items():
        for position, (title, focus) in enumerate(spec["articles"]):
            # Different lengths and ordering; no repeated body paragraph within an
            # article. Shared sections across siblings are deliberate hard overlap.
            count = 4 + position
            sections = list(spec["sections"])
            rotated = sections[position:] + sections[:position]
            chosen = rotated[:min(count, len(rotated))]
            process_count = 3 + position
            process = [(heading, text.format(setting=spec["setting"], focus=focus))
                       for heading, text in PROCESS[:process_count]]
            introduction = (f"{title}\n\n{focus}\n\n"
                            f"This guide follows {spec['setting']}. It treats the immediate task as part of an ordinary working routine, "
                            "with limited space, imperfect information and people who need a clear handover. "
                            "The examples are fictional. They are designed to make the decision process visible, "
                            "including the reasons to test an idea before committing to it.")
            body = introduction + "\n\n" + "\n\n".join(f"{h}\n{p}" for h, p in chosen + process)
            aid = f"B{len(rows) + 1:02}"
            rows.append(dict(id=aid, title=title, body=body, topic=topic,
                             url=f"https://benchmark.example.invalid/{aid.lower()}", eligible="true", existing_links=""))
    target = HERE / "articles.csv"
    with target.open("w", encoding="utf-8", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)
    manifest = {
        "purpose": "Synthetic engineering capacity/performance fixture; not recommendation ground truth",
        "provenance": "Original assistant-authored synthetic prose; no fetched or client content",
        "limitations": ["Shared topic sections and process templates deliberately create correlated passages",
                        "Length is realistic; language diversity and topic distribution are not a production sample",
                        "No independent human relevance labels; no accuracy claim is justified"],
        "article_count": len(rows),
        "sha256": hashlib.sha256(target.read_bytes()).hexdigest(),
        "articles": [{"id": r["id"], "words": len(r["body"].split()), "characters": len(r["body"])} for r in rows],
    }
    (HERE / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"articles": len(rows), "words_min": min(r["words"] for r in manifest["articles"]),
                      "words_max": max(r["words"] for r in manifest["articles"]),
                      "title_body_chars": sum(len(r["title"]) + len(r["body"]) for r in rows)}))


if __name__ == "__main__":
    build()
